
(()=>{const q=(s,p=document)=>p.querySelector(s),qa=(s,p=document)=>[...p.querySelectorAll(s)];const toggle=q('[data-menu-toggle]'),menu=q('[data-mobile-menu]');if(toggle&&menu){toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));menu.classList.toggle('open',open)});qa('a',menu).forEach(a=>a.addEventListener('click',()=>{toggle.setAttribute('aria-expanded','false');menu.classList.remove('open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggle.setAttribute('aria-expanded','false');menu.classList.remove('open')}})}qa('[data-year]').forEach(x=>x.textContent=new Date().getFullYear());const els=qa('.reveal');if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -25px'});els.forEach(e=>io.observe(e))}else els.forEach(e=>e.classList.add('is-visible'));const form=q('#projectForm');if(form){form.addEventListener('submit',e=>{e.preventDefault();const err=q('[data-form-error]',form);if(!form.reportValidity()){if(err){err.hidden=false;err.textContent='Please complete the required fields before sending.'}return}if(err)err.hidden=true;const d=new FormData(form);const val=k=>(d.get(k)||'').toString().trim()||'-';const text=['Hi IfafWebStudio, I would like to discuss a project.','','Name: '+val('name'),'Business: '+val('business'),'Phone / WhatsApp: '+val('phone'),'Email: '+val('email'),'Business Type: '+val('businessType'),'Service: '+val('service'),'Budget: '+val('budget'),'','Project Details:',''+val('details')].join('\n');window.open('https://wa.me/919686044715?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')})}})();

(()=>{document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>img.classList.add('image-load-failed'),{once:true}));})();
